import {contentPageAccess} from '@/features/content/page-access';import {readManaged} from '@/lib/knowledge-admin/server-client';import {EditKnowledge} from '@/features/knowledge-admin/edit';import {ContentState} from '@/components/content-state';import type {Knowledge} from '@/lib/knowledge-admin/types';
export const dynamic='force-dynamic';
export default async function Page({params}:{params:Promise<{id:string}>}){const access=await contentPageAccess(['admin']);if('error'in access)return access.error;const{id}=await params;if(!/^k-[0-9a-f]{56}$/.test(id))return <ContentState kind="not-found"/>;const r=await readManaged<Knowledge>('/api/v3/admin/knowledge/'+id,access.cookie);return r.ok?<EditKnowledge initial={r.data}/>:<ContentState kind={r.status===404?'not-found':'unavailable'}/>}
